def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    max_prev_bid = 0.0
    min_prev_bid = None
    eric_like_bid = None
    cindy_like_bid = None

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > max_prev_bid:
                    max_prev_bid = float(bid)
                if min_prev_bid is None or float(bid) < min_prev_bid:
                    min_prev_bid = float(bid)
                if 65.0 <= float(bid) <= 75.0:
                    eric_like_bid = float(bid)
                if float(bid) >= 110.0:
                    cindy_like_bid = float(bid)

    if not alive_opps:
        return min(float(budget), 1.0)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if day >= 8:
        urgency += 1

    if supply <= 16:
        urgency += 1

    if cindy_like_bid is not None and hp > 4 and no_water_days == 0:
        if supply >= 20:
            base = 8.0
        else:
            base = 18.0
        return min(float(budget), base)

    target = 0.0

    if urgency >= 5:
        if cindy_like_bid is not None:
            target = min(float(budget), max(96.0, cindy_like_bid + 1.0))
        else:
            ref = eric_like_bid if eric_like_bid is not None else max_prev_bid
            target = min(float(budget), max(85.0, ref + 3.0))
    elif urgency >= 3:
        ref = eric_like_bid if eric_like_bid is not None else 70.0
        target = max(72.0, ref + 2.0)
    elif urgency >= 1:
        if supply >= 22:
            target = 28.0
        elif supply >= 19:
            target = 42.0
        else:
            ref = eric_like_bid if eric_like_bid is not None else 70.0
            target = max(55.0, ref + 1.0)
    else:
        if supply >= 22:
            target = 5.0
        elif supply >= 19:
            target = 15.0
        else:
            target = 26.0

    reserve_days = max(0, 10 - int(day))
    soft_cap = float(budget)
    if reserve_days > 0 and urgency < 5:
        keep_reserve = reserve_days * 18.0
        soft_cap = max(0.0, float(budget) - keep_reserve)
        if soft_cap <= 0.0:
            soft_cap = min(float(budget), 22.0 if urgency == 0 else 40.0)

    bid = min(float(budget), target, soft_cap if urgency < 5 else float(budget))

    if hp <= 2 or no_water_days >= 2:
        bid = min(float(budget), max(bid, 98.0 if cindy_like_bid is not None else 78.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer who is applying max pressure.
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If someone was bidding far above typical salary, treat as a pressure leader.
    pressure_leader = False
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        if highest_prev_bid >= 1.2 * DAILY_SALARY:  # ~108+
            pressure_leader = True

    # Base bid: aim to secure enough water without fully matching pressure.
    # Convert supply to an approximate fraction of a day's requirement.
    # If supply is low, we bid higher.
    supply_ratio = 0.0
    if WATER_REQ > 0:
        supply_ratio = supply / float(WATER_REQ)

    # Ensure indices are int when using any lists.
    # (No lists used for indexing, but keep safe.)

    # Risk adjustment: if we've already gone without water, bid more aggressively.
    if no_water_days >= 2 or hp <= 2:
        urgency = 1.0
    elif no_water_days == 1 or hp <= 4:
        urgency = 0.7
    else:
        urgency = 0.45

    # Aggressiveness vs Cindy-like pressure.
    if pressure_leader:
        # Do not chase; bid enough to avoid being starved, but conserve budget.
        target = DAILY_SALARY * (0.35 + 0.35 * urgency)
    else:
        target = DAILY_SALARY * (0.55 + 0.35 * urgency)

    # Scale with supply: lower supply => higher bid.
    # supply range is [15,25], map to multiplier [1.15,0.85]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if t < 0.0:
            t = 0.0
        if t > 1.0:
            t = 1.0
    else:
        t = 0.5
    supply_mult = 1.15 - 0.30 * t

    bid = target * supply_mult

    # Never exceed budget; never negative.
    bid = max(0.0, min(budget, bid))

    # If budget is very low, still try to bid something proportional.
    if budget <= DAILY_SALARY * 0.15:
        bid = min(bid, budget)

    # Small day-based variation to reduce predictability.
    # Keep deterministic-ish but not too large.
    if day % 3 == 0:
        bid *= 1.03
    elif day % 3 == 1:
        bid *= 0.98

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        # No opponents, bid conservatively to save budget
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # If no opponent bids from yesterday, use a default strategy
    if not yesterday_bids:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)

    # React to very aggressive bids from yesterday
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            # If HP is good, conserve budget against very high bids
            return min(my_status['budget'], DAILY_SALARY * 0.3)
        # If HP is low, bid aggressively to survive
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Default strategy: bid slightly above the highest previous bid or a safe percentage of salary
    # This targets Eric's consistent 70.0 bid (150 * 0.5 = 75, max(75, 70.0 + 1.5) = 75)
    return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1
    fair_share_bid = (supply / num_agents) * 1.1
    if my_status['hp'] < 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    if my_status['hp'] > 8:
        return min(my_status['budget'], fair_share_bid * 0.8)
    return min(my_status['budget'], max(fair_share_bid, DAILY_SALARY * 0.4))
